insert into products (slug, name, description, long_description, category_id, spice_note, dietary, badge, tagline, rating, review_count, published) values ('besan-motichoor-laddu', 'Besan Motichoor Laddu', 'Tiny chickpea pearls slow fried in fragrant desi ghee, blended with saffron sugar syrup.', 'Melt-in-mouth motichoor pearls fried in fragrant desi ghee, bound with Kashmiri saffron syrup and melon seeds.', (select id from categories where slug='mithai'), 'mild', ARRAY['pure-veg','cow-ghee']::text[], 'Kashmiri Saffron', 'Pure Ghee Mithai', 4.9, 1940, true) on conflict (slug) do update set name=excluded.name, description=excluded.description, long_description=excluded.long_description, category_id=excluded.category_id, spice_note=excluded.spice_note, dietary=excluded.dietary, badge=excluded.badge, tagline=excluded.tagline, rating=excluded.rating, review_count=excluded.review_count, published=true;
